program
	.command("list-messages")
	.summary("list-messages [--after <after:iso-8601>] [--before <before:iso-8601>] [--chat-jid <chat-jid>] [--context-after <context-after:number>] [--context-before <context-before:number>] [--raw <json>]")
	.description("(reads local cache; works while disconnected) Search and page through cached WhatsApp messages, optionally filtering by chat, sender, time range, and substring; can include surrounding context messages. Read-only; no side effects. Use get_message_context to expand around a single known message ID, or request_sync to backfill missing history. Returns a human-readable formatted text block listing matching messages and, when more results remain, a `next_cursor` line; edited messages show an `[edited]` marker and messages deleted for everyone keep their text behind a `[deleted <time> UTC]` marker. Continue stable walks with that `next_cursor` passed back as `cursor`, because the legacy `page` offset can repeat or miss messages when new messages arrive between calls. With `format` set to `json` it returns the same messages as a JSON object instead: a `messages` array of message objects (each with `sender_name`; `edited`, `revoked` and `revoked_at` appear only when set) and `next_cursor` when more results remain.")
	.usage("[--after <after:iso-8601>] [--before <before:iso-8601>] [--chat-jid <chat-jid>] [--context-after <context-after:number>] [--context-before <context-before:number>] [--raw <json>]")
	.option('--raw <json>', 'Provide raw JSON arguments to the tool, bypassing flag parsing.')

	.addOption(defineOption("--after <after:iso-8601>", "ISO-8601 UTC lower bound on message timestamp (exclusive)"))
	.addOption(defineOption("--before <before:iso-8601>", "ISO-8601 UTC upper bound on message timestamp (exclusive)"))
	.addOption(defineOption("--chat-jid <chat-jid>", "filter to messages in this chat (WhatsApp JID: individual as `<digits>@s.whatsapp.net` or bare phone digits, group as `<digits>-<timestamp>@g.us`) (example: example-id)"))
	.addOption(defineOption("--context-after <context-after:number>", "messages to include after each match (default 1, capped at 20 server-side) (default: 1; example: 1)", (value) => parseFiniteNumber(value)))
	.addOption(defineOption("--context-before <context-before:number>", "messages to include before each match (default 1, capped at 20 server-side) (default: 1; example: 1)", (value) => parseFiniteNumber(value)))
